import json
import itertools

def solve():
    houses = [1, 2, 3, 4, 5, 6]

    names = ["Carol", "Peter", "Eric", "Arnold", "Alice", "Bob"]
    cigars = ["blends", "yellow monster", "pall mall", "blue master", "dunhill", "prince"]

    solutions = []

    # Permute names across houses 1..6
    for name_perm in itertools.permutations(names):
        house_name = {house: name_perm[house - 1] for house in houses}
        name_house = {name_perm[i]: i + 1 for i in range(len(name_perm))}

        # Apply direct name constraints
        # 6. Eric is in the sixth house.
        if name_house["Eric"] != 6:
            continue
        # 8. Peter is in the first house.
        if name_house["Peter"] != 1:
            continue
        # 9. Bob is in the third house.
        if name_house["Bob"] != 3:
            continue
        # 7. Carol and Eric are next to each other.
        if abs(name_house["Carol"] - name_house["Eric"]) != 1:
            continue

        # Permute cigars across houses with fixed constraints
        # 2. The person who smokes Blue Master is in the fifth house.
        # 5. The person partial to Pall Mall is in the third house.
        remaining_houses = [h for h in houses if h not in (3, 5)]
        remaining_cigars = [c for c in cigars if c not in ("pall mall", "blue master")]

        for cigar_perm in itertools.permutations(remaining_cigars):
            house_cigar = {
                3: "pall mall",
                5: "blue master",
            }
            for idx, house in enumerate(remaining_houses):
                house_cigar[house] = cigar_perm[idx]
            cigar_house = {house_cigar[h]: h for h in houses}

            # Apply cigar-related constraints

            # 4. There is one house between Yellow Monster and blends. abs difference is 2.
            if abs(cigar_house["yellow monster"] - cigar_house["blends"]) != 2:
                continue

            # 1. Arnold is somewhere to the left of the person who smokes blends.
            if not (name_house["Arnold"] < cigar_house["blends"]):
                continue

            # 3. Arnold is somewhere to the left of the Prince smoker.
            if not (name_house["Arnold"] < cigar_house["prince"]):
                continue

            # All constraints satisfied; record solution
            solution_rows = []
            for h in houses:
                solution_rows.append([str(h), house_name[h], house_cigar[h]])

            solutions.append({
                "solution": {
                    "header": ["House", "Name", "favorite cigar"],
                    "rows": solution_rows
                }
            })

    # Assuming unique solution
    if solutions:
        return solutions[0]
    else:
        return {
            "solution": {
                "header": ["House", "Name", "favorite cigar"],
                "rows": []
            }
        }

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, indent=2))
